styles.css:
  *{box-sizing:border-box}
  html{scroll-behavior:smooth}
  html,body{margin:0}
  body{background:#F1F2EE}
  a{color:inherit}

  :root{
    --bg:#F1F2EE;
    --ink:#0E1216;
    --body:#3A4046;
    --dim:#6B7076;
    --panel:#F1F2EE;
    --grid:rgba(14,18,22,.035);
    --hair:rgba(14,18,22,.30);
    --soft:rgba(14,18,22,.06);
    --accent:#FF4A17;
    --onaccent:#FFFFFF;
  }
  :root[data-theme="dark"]{
    --bg:#0E1216;
    --ink:#F1F2EE;
    --body:#C4C9C6;
    --dim:#8B9296;
    --panel:#131A1F;
    --grid:rgba(241,242,238,.03);
    --hair:rgba(241,242,238,.28);
    --soft:rgba(241,242,238,.07);
    --accent:#FF4A17;
    --onaccent:#FFFFFF;
  }

  .shell{max-width:1400px;margin:0 auto;padding-left:56px;padding-right:56px}
  .nav{display:flex;align-items:center;justify-content:space-between;gap:24px;padding-top:16px;padding-bottom:16px}
  .brand{display:flex;align-items:center;gap:12px;text-decoration:none;min-width:0}
  .brand-mark{width:22px;height:22px;background:var(--accent);display:block;flex:none}
  .brand-name{font-weight:700;font-size:16px;letter-spacing:-.01em;white-space:nowrap}
  .brand-sub{font-family:'JetBrains Mono',monospace;font-size:10.5px;color:var(--dim);white-space:nowrap}
  .nav-right{display:flex;align-items:center;gap:6px;font-family:'JetBrains Mono',monospace;font-size:11px;letter-spacing:.08em}
  .nav-link{padding:8px 10px;text-decoration:none}
  .nav-link:hover{color:var(--accent)}
  .theme-toggle{all:unset;cursor:pointer;margin-left:4px;display:flex;align-items:center;gap:7px;border:2px solid var(--ink);padding:5px 8px;background:var(--panel)}

  .hero{min-height:650px;display:grid;grid-template-columns:minmax(0,1.25fr) minmax(280px,.75fr);gap:72px;align-items:center;padding-top:72px;padding-bottom:84px}
  .eyebrow{font-family:'JetBrains Mono',monospace;font-size:12px;letter-spacing:.14em;color:var(--dim);margin-bottom:16px}
  .hero-title{font-weight:700;font-size:clamp(56px,7vw,102px);line-height:.96;letter-spacing:-.055em;margin:0;text-transform:uppercase}
  .hero-prefix{display:block}
  .role-window{position:relative;display:block;overflow:hidden;height:1.08em;color:var(--accent)}

  .hero-jump{display:inline-block;margin-top:34px;text-decoration:none;border-bottom:2px solid var(--ink);padding-bottom:4px;font-family:'JetBrains Mono',monospace;font-size:11px;letter-spacing:.1em}
  .hero-jump:hover{color:var(--accent);border-color:var(--accent)}

  .portrait{border:2px solid var(--ink);padding:8px;background:var(--panel);position:relative}
  .portrait-meta{display:flex;justify-content:space-between;gap:12px;font-family:'JetBrains Mono',monospace;font-size:10px;color:var(--dim);letter-spacing:.06em;padding:8px 2px 2px}
  .corner-a,.corner-b{position:absolute;width:10px;height:10px;background:var(--accent)}
  .corner-a{top:-2px;left:-2px}.corner-b{bottom:-2px;right:-2px}

  .work{padding-top:72px;padding-bottom:86px}
  .section-head{display:flex;align-items:flex-end;justify-content:space-between;gap:24px;margin-bottom:28px}
  .section-kicker{font-family:'JetBrains Mono',monospace;font-size:11px;letter-spacing:.14em;color:var(--dim);margin-bottom:8px}
  .section-title{font-size:42px;letter-spacing:-.04em;margin:0}
  .section-link{font-family:'JetBrains Mono',monospace;font-size:10.5px;letter-spacing:.08em;text-decoration:none;color:var(--dim);white-space:nowrap}
  .section-link:hover{color:var(--accent)}

  .projects{display:flex;flex-direction:column;gap:34px}
  .project{display:block;text-decoration:none;border:2px solid var(--ink);background:var(--panel);transition:transform .18s ease,box-shadow .18s ease}
  .project:hover{transform:translate(-3px,-3px);box-shadow:8px 8px 0 var(--accent);color:inherit}
  .project-image{width:100%;height:clamp(260px,34vw,470px);display:block;background:var(--soft)}
  .project-copy{text-align:center;border-top:2px solid var(--ink);padding:22px 24px 24px}
  .project-title{font-size:32px;font-weight:700;letter-spacing:-.03em;line-height:1.1;margin:0 0 8px}
  .project-description{font-size:15px;line-height:1.55;color:var(--body);margin:0 auto;max-width:62ch}

  .footer{border-top:2px solid var(--ink)}
  .footer-inner{display:flex;align-items:center;justify-content:space-between;gap:24px;padding-top:28px;padding-bottom:34px}
  .footer-copy{font-size:14px;color:var(--body)}
  .footer-links{display:flex;gap:18px;flex-wrap:wrap;font-family:'JetBrains Mono',monospace;font-size:10.5px;letter-spacing:.08em}
  .footer-links a{text-decoration:none}
  .footer-links a:hover{color:var(--accent)}

  @media (prefers-reduced-motion:reduce){
      html{scroll-behavior:auto}
  }

  @media (max-width:900px){
    .shell{padding-left:28px;padding-right:28px}
    .brand-sub{display:none}
    .hero{grid-template-columns:1fr;min-height:auto;gap:42px;padding-top:56px;padding-bottom:64px}
    .portrait{max-width:520px}
    .nav-right{gap:2px}
    .section-head{align-items:flex-start;flex-direction:column}
  }

  @media (max-width:620px){
    .shell{padding-left:18px;padding-right:18px}
    .nav{gap:12px}
    .brand-name{font-size:14px}
    .hero{padding-top:42px;padding-bottom:52px}
    .hero-title{font-size:clamp(46px,14vw,70px)}
      .work{padding-top:54px;padding-bottom:64px}
    .section-title{font-size:34px}
    .section-link{display:none}
    .project-copy{padding:18px}
    .project-title{font-size:26px}
    .project-description{font-size:14px}
    .footer-inner{align-items:flex-start;flex-direction:column}
  }

  .intro{padding-top:82px;padding-bottom:54px}
  .eyebrow{font-family:'JetBrains Mono',monospace;font-size:11px;letter-spacing:.14em;color:var(--dim);margin-bottom:12px}
  h1{font-size:clamp(54px,7vw,92px);line-height:.95;letter-spacing:-.055em;text-transform:uppercase;margin:0}

  .index-wrap{padding-bottom:110px;display:grid;gap:64px}
  .category{display:grid;grid-template-columns:minmax(180px,280px) minmax(0,1fr);gap:56px;align-items:start}
  .category-title{font-size:28px;font-weight:700;letter-spacing:-.035em;margin:0}
  .skill-list{display:grid;gap:18px}
  .skill-row{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:24px;align-items:center;min-height:34px}
  .skill-name{font-size:18px;font-weight:600}
  .evidence{display:flex;align-items:center;gap:8px;min-height:28px}
  .dot{width:24px;height:24px;border-radius:50%;display:block;background:var(--accent);border:4px solid #0E1216;transition:transform .15s ease}
  .dot:hover{transform:scale(1.14)}


body{background:var(--bg);color:var(--ink);font-family:'Space Grotesk',system-ui,sans-serif}
.site-grid{min-height:100vh;background-image:linear-gradient(var(--grid) 1px,transparent 1px),linear-gradient(90deg,var(--grid) 1px,transparent 1px);background-size:44px 44px}
.site-header{position:sticky;top:0;z-index:40;background:var(--bg);border-bottom:2px solid var(--ink)}
.nav-right,.hero-jump,.footer-links{font-size:14px;letter-spacing:.04em}
.nav-link,.theme-toggle{min-height:44px;display:flex;align-items:center;justify-content:center}
.theme-toggle{box-sizing:border-box;padding:6px 10px}
.theme-toggle svg{stroke:var(--dim)}
.theme-toggle .sun{stroke:var(--accent)}
[data-theme="dark"] .theme-toggle .sun{stroke:var(--dim)}
[data-theme="dark"] .theme-toggle .moon{stroke:var(--accent)}
.theme-divider{width:1px;height:16px;background:var(--hair)}
a:focus-visible,button:focus-visible{outline:3px solid var(--accent);outline-offset:5px}
.skip-link{position:fixed;top:8px;left:8px;transform:translateY(-160%);z-index:100;background:var(--bg);padding:12px}
.skip-link:focus{transform:none}
.hero-title{font-size:clamp(52px,6.5vw,90px)}
.role-window{height:2.08em}
.portrait img{display:block;width:100%;height:440px;object-fit:cover}
.project-image{object-fit:cover}
.project-description{font-size:16px}
.section-kicker,.eyebrow,.portrait-meta{font-size:12px}
.index-wrap{max-width:1200px}
.category{gap:56px}
.evidence{gap:0}
.dot{width:40px;height:40px;border:0;background:none;display:grid;place-items:center}
.dot::before{content:'';width:24px;height:24px;box-sizing:border-box;border-radius:50%;background:#FF4A17;border:4px solid #0E1216}
.skill-row{min-height:40px}
.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip-path:inset(50%);white-space:nowrap;border:0}
#work,#contact,.project{scroll-margin-top:110px}
@media(max-width:1100px){.hero{gap:36px;grid-template-columns:minmax(0,1.2fr) minmax(240px,.8fr)}}
@media(max-width:900px){.hero{grid-template-columns:1fr}.hero-title{font-size:clamp(52px,10vw,84px)}.role-window{height:2.05em}.portrait{width:100%;max-width:520px}.category{grid-template-columns:1fr;gap:20px}}
@media(max-width:620px){.nav{flex-wrap:wrap;gap:10px;padding-top:12px;padding-bottom:10px}.brand{width:100%}.nav-right{width:100%;justify-content:space-between}.nav-link{padding:6px 8px}.theme-toggle{margin-left:auto}.hero-title{font-size:clamp(40px,11vw,68px)}.hero{gap:28px}.portrait img{height:auto;aspect-ratio:1/1;object-fit:cover}.skill-name{font-size:16px}.skill-row{gap:8px}.category-title{font-size:26px}.index-wrap{gap:48px;padding-bottom:64px}.dot{width:32px}.intro{padding-top:48px;padding-bottom:40px}.footer-copy{font-size:16px}}
@media(prefers-reduced-motion:reduce){*,*::before,*::after{animation:none!important;transition:none!important;scroll-behavior:auto!important}.project:hover{transform:none}}

.nav-link[aria-current="page"]{color:var(--accent)}
.portrait-initials{height:440px;display:flex;align-items:center;justify-content:center;font-size:clamp(100px,14vw,190px);font-weight:700;letter-spacing:-.08em;background:var(--soft)}
.portrait-initials span{color:var(--accent)}
@media(max-width:620px){.portrait-initials{height:auto;aspect-ratio:1;font-size:clamp(100px,35vw,180px)}}

.role-word{position:absolute;inset:0 auto auto 0;display:block;font-size:.88em;max-width:100%;white-space:normal;opacity:1;transform:none;overflow-wrap:normal}

/* Conversational hero; navigation and metadata retain their existing treatment. */
.hero .eyebrow{font-family:'Space Grotesk',system-ui,sans-serif;font-size:clamp(20px,2vw,26px);line-height:1.4;letter-spacing:-.02em;color:var(--body);margin-bottom:20px}
.hero-title{text-transform:none;line-height:1.08;letter-spacing:-.04em}
.hero .role-window{height:2.2em}
.project-description{line-height:1.65}

/* NightShift: the first project story, shaped around its actual chronology. */
.case-page{background:var(--bg)}
.case-intro{padding-top:48px;padding-bottom:64px;max-width:1200px}
.case-back,.case-play,.case-end a{font-family:'JetBrains Mono',monospace;font-size:14px;text-underline-offset:5px}
.case-kicker{margin:48px 0 14px;color:var(--body);font-size:18px}
.case-intro h1{text-transform:none;font-size:clamp(48px,8vw,104px);line-height:1.04;letter-spacing:-.055em}
.case-lead{font-size:clamp(24px,3vw,34px);line-height:1.35;letter-spacing:-.025em;max-width:30ch;margin:28px 0 20px}
.case-summary{font-size:18px;line-height:1.7;max-width:64ch;color:var(--body)}
.case-facts{display:grid;grid-template-columns:1.7fr 1fr 1fr;gap:32px;margin:36px 0}
.case-facts dt{font-family:'JetBrains Mono',monospace;font-size:12px;color:var(--dim);margin-bottom:10px}
.case-facts dd{font-size:16px;line-height:1.6;margin:0}
.case-play{display:inline-block;padding:12px 0;color:var(--ink);text-decoration-thickness:2px}
.case-play:hover,.case-back:hover,.case-contents a:hover{color:var(--accent)}
.case-layout{max-width:1200px;display:grid;grid-template-columns:200px minmax(0,1fr);gap:64px;align-items:start;padding-bottom:80px}
.case-contents{position:sticky;top:106px;display:grid;gap:14px;padding-top:6px;font-size:14px;line-height:1.5}
.case-contents>span{font-family:'JetBrains Mono',monospace;font-size:12px;color:var(--dim);margin-bottom:8px}
.case-contents a{text-decoration:none}
.case-story{min-width:0;max-width:72ch}
.case-story section{margin-bottom:76px;scroll-margin-top:110px}
.case-story h2{font-size:clamp(28px,3.2vw,40px);line-height:1.18;letter-spacing:-.035em;margin:0 0 28px;text-wrap:balance}
.case-story h3{font-size:22px;line-height:1.35;letter-spacing:-.02em;margin:36px 0 16px}
.case-story p,.case-story li{font-size:18px;line-height:1.8;color:var(--body)}
.case-story p{margin:0 0 24px}
.case-story ul{padding-left:22px}
.case-story li{margin-bottom:12px}
.media-placeholder{margin:36px 0 0;min-height:220px;display:flex;align-items:center;justify-content:center;border:2px dashed var(--hair);background:var(--soft);padding:32px}
.media-placeholder>div{max-width:54ch}
.media-kind{font-family:'JetBrains Mono',monospace;font-size:13px;color:var(--ink)}
.media-placeholder p,.case-story .media-placeholder p{font-size:16px;line-height:1.6;margin:12px 0 0;color:var(--body)}
.media-wide{aspect-ratio:16/7;min-height:260px}
.case-end{display:flex;flex-wrap:wrap;justify-content:space-between;gap:24px}
@media(max-width:900px){.case-layout{grid-template-columns:1fr;gap:48px}.case-contents{position:static;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px 24px}.case-contents>span{grid-column:1/-1}.case-facts{grid-template-columns:1fr 1fr}.case-facts>div:first-child{grid-column:1/-1}.case-story{max-width:72ch}}
@media(max-width:620px){.case-intro{padding-top:28px;padding-bottom:48px}.case-kicker{margin-top:36px;font-size:16px}.case-facts{grid-template-columns:1fr;gap:24px}.case-story p,.case-story li{font-size:17px;line-height:1.75}.case-story section{margin-bottom:56px;scroll-margin-top:140px}.media-placeholder{padding:22px;min-height:190px}.media-wide{aspect-ratio:auto}.case-end a{line-height:1.7}}

/* Project story navigation and end matter. */
.case-intro h1{margin-top:44px}
.case-tagline{font-size:clamp(20px,2.4vw,28px);line-height:1.4;letter-spacing:-.02em;margin:16px 0 28px}
.case-intro .media-wide{margin-top:28px;margin-bottom:30px}
.case-section-label{font-family:'JetBrains Mono',monospace;font-size:12px!important;line-height:1.5!important;letter-spacing:.04em;color:var(--dim)!important;margin-bottom:12px!important}
.case-contents{gap:4px;max-height:calc(100vh - 130px);overflow-y:auto;padding-right:12px}
.case-contents a{display:flex;align-items:center;min-height:36px;font-size:12px;padding:6px 0}
.case-contents a span{display:inline-block;transform-origin:left center;transition:transform .18s ease,color .18s ease}
.case-contents a:hover span,.case-contents a:focus-visible span{transform:scale(1.1667);color:var(--accent)}
.case-details{border-top:2px solid var(--ink);padding-top:32px;margin-bottom:48px}
.case-story .case-resources{margin-bottom:36px}
.case-resources h2{font-family:'JetBrains Mono',monospace;font-size:14px;letter-spacing:0;margin-bottom:12px}
.case-story .resource-intro{font-size:16px;line-height:1.6;margin-bottom:24px}
.case-story .resource-list{padding:0;list-style:none;display:grid;grid-template-columns:1fr 1fr;gap:24px 28px}
.case-story .resource-list li{margin:0;display:flex;gap:12px;font-size:16px;line-height:1.5;min-width:0}
.resource-list svg{width:24px;height:24px;flex:none;color:var(--ink);margin-top:2px}
.resource-list a{font-weight:600;text-underline-offset:4px;text-decoration-thickness:1px}
.resource-list a:hover{color:var(--accent)}
.resource-maker{display:block;color:var(--dim);font-size:12px;line-height:1.6;margin-top:4px}
.case-story .resource-list p{font-size:14px;line-height:1.6;margin:6px 0 0}
.case-details .case-facts{margin:0;gap:24px;grid-template-columns:1.4fr 1fr 1fr}
@media(max-width:900px){.case-contents{max-height:none;overflow:visible;padding-right:0}.case-contents a{font-size:14px;min-height:44px}.case-contents a:hover span,.case-contents a:focus-visible span{transform:none}}
@media(hover:none){.case-contents a{font-size:14px;min-height:44px}.case-contents a span{transform:none!important}}
@media(max-width:620px){.case-details .case-facts,.case-story .resource-list{grid-template-columns:1fr}.case-intro h1{margin-top:32px}}

