.layout-block>.content-media{width:100%}.layout-block>.content-media img{object-fit:contain}
.case-story .layout-block>p:first-child{margin-top:0}.case-intro .builtin-projectTitle h1{margin-top:24px}.case-intro .layout-block>.content-media{max-width:1000px}
.media-placeholder figcaption{font-size:14px;line-height:1.6;margin-top:12px}
