/* Portfolio-wide navigation and evidence usability. */
html{scroll-padding-top:calc(var(--header-height,100px) + 24px)}
main{min-width:0}img,video{max-width:100%}
.nav{position:relative}.nav-right{min-width:0;flex-wrap:wrap}
.work-toggle{width:44px;height:44px;flex:none}
.work-dropdown{width:320px;max-width:calc(100vw - 24px);max-height:calc(100dvh - var(--header-height,100px) - 24px);overflow-y:auto;overscroll-behavior:contain}
.work-group-projects a{min-height:44px;overflow-wrap:anywhere}
.work-group summary{min-height:44px}
.work-group summary:focus-visible,summary:focus-visible,input:focus-visible,select:focus-visible,textarea:focus-visible{outline:3px solid var(--accent);outline-offset:3px}
.page-quicklinks{display:flex;flex-wrap:wrap;gap:4px 24px;margin:28px 0 8px;padding:14px 0;border-block:1px solid var(--hair)}
.page-quicklinks a{display:inline-flex;align-items:center;min-height:44px;font:14px/1.5 'JetBrains Mono',monospace;text-decoration:none;text-underline-offset:5px}
.page-quicklinks a:hover,.page-quicklinks a:focus-visible{text-decoration:underline;color:var(--accent)}
.work-collection,.category,.case-story section{scroll-margin-top:calc(var(--header-height,100px) + 24px)}
.work-page .projects{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:28px}
.work-page .project{min-width:0;display:flex;flex-direction:column}
.work-page .project-image{height:auto;aspect-ratio:16/10;object-fit:cover}
.work-page .project-copy{flex:1;display:flex;flex-direction:column;text-align:left;padding:22px}
.work-page .project-title{font-size:25px;line-height:1.2}
.work-page .project-description{margin:0;font-size:15px}
.project-destination{display:block;margin-top:auto;padding-top:22px;font:12px/1.6 'JetBrains Mono',monospace;color:var(--accent)}
.text-project .project-copy{border-top:0}
.work-page .collection-illustration .project-image,.work-page .collection-renders .project-image,.work-page .collection-animation .project-image{aspect-ratio:1;object-fit:contain;background:var(--soft)}
.project:focus-visible{outline-offset:6px;box-shadow:6px 6px 0 var(--accent-base)}
.index-wrap .category{border-top:1px solid var(--hair);padding-top:28px}
.skill-row{grid-template-columns:minmax(0,1fr) minmax(44px,55%);gap:4px 20px;align-items:start}
.skill-name{padding-top:11px}
.evidence{flex-wrap:wrap;justify-content:flex-end;min-width:0}
.dot{width:44px;height:44px;flex:0 0 44px;transform:none!important}
.dot:hover::before,.dot:focus-visible::before{transform:scale(1.12)}
.project-tooltip{position:fixed;z-index:100;background:var(--ink);color:var(--bg);border:1px solid var(--bg);padding:10px 13px;max-width:calc(100vw - 24px);font:14px/1.5 'JetBrains Mono',monospace;overflow-wrap:anywhere}
.project-tooltip[hidden]{display:none}
.role-pause{display:block;width:fit-content;margin-top:16px;padding:8px 0;min-height:44px;border:0;border-bottom:1px solid var(--hair);color:var(--body);background:none;font:12px/1.5 'JetBrains Mono',monospace;cursor:pointer}
.footer-links a{min-height:44px;display:inline-flex;align-items:center}.footer-links{gap:8px 22px}
.intro>p{max-width:65ch;line-height:1.7;color:var(--body)}
@media(max-width:1050px){.work-page .projects{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media(max-width:700px){
 .nav{display:flex;flex-wrap:wrap;justify-content:center;gap:8px;padding-top:12px;padding-bottom:10px}
 .brand{width:100%;justify-content:center}.brand-name{font-size:16px}
 .nav-right{width:100%;justify-content:center;gap:4px;font-size:12px}
 .nav-link{padding:6px 8px}.theme-toggle{margin-left:4px;padding:6px 8px}
 .work-menu{position:static}.work-dropdown{left:12px;right:12px;top:100%;width:auto}
 .work-page .projects{grid-template-columns:1fr}.work-page .project-image{max-height:420px}
 .work-collection{margin-top:44px}.page-quicklinks{gap:4px 18px}
 .skill-row{grid-template-columns:1fr;gap:0}.evidence{justify-content:flex-start}.skill-name{padding-top:4px}
 .case-contents a{min-height:44px}.case-layout{gap:32px}.case-story{width:100%}
}
@media(max-width:360px){.nav-right{gap:0;font-size:11px}.nav-link{padding-inline:5px}.work-toggle{width:36px}.theme-toggle{padding-inline:6px}.brand-name{font-size:14px}}
@media(forced-colors:active){.dot::before{background:LinkText;border-color:CanvasText}.project-tooltip{border:2px solid CanvasText}.brand-mark{background:CanvasText}}
.work-page .collection-films .project-image{aspect-ratio:3/4;object-fit:contain;background:var(--soft)}

/* Compact skill families retain individual deep links and project evidence. */
.index-wrap{gap:36px;max-width:1400px}
.index-wrap .category{grid-template-columns:1fr;gap:18px;padding-top:24px}
.category .skill-list{grid-template-columns:repeat(2,minmax(0,1fr));gap:0 40px}
.category .skill-row{position:relative;grid-template-columns:minmax(0,1fr) auto;gap:8px 16px;padding:12px 0;border-bottom:1px solid var(--hair);align-items:center}
.skill-label{min-width:0}.skill-name{display:block;padding:0;font-size:17px;line-height:1.4}
.skill-detail{display:block;margin-top:4px;font-size:13px;line-height:1.6;color:var(--body)}
.skill-detail span,.skill-anchor{scroll-margin-top:calc(var(--header-height,100px) + 40px)}
.skill-detail span:target{color:var(--accent);text-decoration:underline;text-underline-offset:4px}
.skill-row:has(:target){background:var(--soft);box-shadow:-4px 0 0 var(--accent)}
.skill-anchor{position:absolute;top:0;left:0}
.category .evidence{max-width:176px}.category .dot{width:32px;height:44px;flex-basis:32px}
.category .dot::before{width:18px;height:18px;border-width:3px}
.role-controls{display:flex;align-items:center;gap:8px;margin-top:16px}
.role-controls .role-pause{margin:0;margin-right:8px}
.role-arrow{display:inline-flex;align-items:center;justify-content:center;flex:none;width:44px;height:44px;padding:0;border:1px solid var(--hair);color:var(--ink);background:transparent;cursor:pointer}
.role-arrow svg{width:16px;height:16px;fill:none;stroke:currentColor;stroke-width:1.7}
.role-previous svg{transform:rotate(90deg)}.role-next svg{transform:rotate(-90deg)}
.role-arrow:hover,.role-arrow:focus-visible{color:var(--accent);border-color:var(--accent)}
.role-arrow:disabled{opacity:.4;cursor:default}
.role-word{text-decoration:none}.role-word:hover{text-decoration:underline;text-decoration-thickness:2px;text-underline-offset:8px}
.role-word:focus-visible{outline-offset:-3px;text-decoration:underline;text-decoration-thickness:2px}
#work #daisychain .project-image,#work #lone-nemo .project-image{object-fit:contain;background:var(--soft)}
@media(max-width:900px){.category .skill-list{grid-template-columns:1fr}.category .evidence{max-width:55%}}
@media(max-width:700px){
 .nav{flex-wrap:nowrap;justify-content:space-between;gap:8px;padding:10px 16px}
 .brand{width:auto;flex:none;justify-content:flex-start;gap:6px}.brand-mark{width:12px;height:12px}.brand-name{font-size:14px}
 .nav-right{width:auto;flex-wrap:nowrap;justify-content:flex-end;gap:0;font-size:11px;letter-spacing:0}
 .nav-link{padding:6px}.work-toggle{width:28px}.theme-toggle{width:32px;padding:6px;margin-left:4px;gap:0}
 .theme-divider,.theme-toggle .moon{display:none}
 [data-theme="dark"] .theme-toggle .sun{display:none}[data-theme="dark"] .theme-toggle .moon{display:block}
 .category .skill-row{grid-template-columns:minmax(0,1fr);gap:2px;padding:10px 0}
 .category .evidence{max-width:100%;justify-content:flex-start}
 .skill-name{font-size:16px}.role-controls{gap:6px}.role-controls .role-pause{margin-right:4px;font-size:11px}
}
@media(max-width:400px){.nav{padding-inline:10px;gap:4px}.brand-name{font-size:13px}.brand-mark{width:9px;height:9px}.brand{gap:5px}.nav-right{font-size:10.5px}.nav-link{padding-inline:4px}.theme-toggle{margin-left:2px;width:28px}}
@media(max-width:340px){.nav{padding-inline:8px}.brand-name{font-size:12px}.brand-mark{display:none}.nav-right{font-size:10px}.nav-link{padding-inline:3px}.work-toggle{width:24px}.theme-toggle{width:26px}}

